def now():
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


def bytes_sha(data):
    return hashlib.sha256(data).hexdigest()


def digest(path):
    value = hashlib.sha256()
    with open(path, "rb") as source:
        for block in iter(lambda: source.read(1024 * 1024), b""):
            value.update(block)
    return value.hexdigest()


def read(path):
    with open(path, encoding="utf-8") as source:
        return json.load(source)


def sync_directory(path):
    descriptor = os.open(path, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


def save(path, value):
    path = pathlib.Path(path)
    raw = (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2) + "\n").encode()
    temporary = path.with_name(path.name + ".next-" + str(os.getpid()))
    descriptor = os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    try:
        with os.fdopen(descriptor, "wb", closefd=False) as output:
            output.write(raw)
            output.flush()
            os.fsync(descriptor)
    finally:
        os.close(descriptor)
    os.replace(temporary, path)
    sync_directory(path.parent)


def private_directory(path, create=False):
    path = pathlib.Path(path).absolute()
    if create:
        path.mkdir(parents=True, exist_ok=True, mode=0o700)
    info = path.lstat()
    if not stat.S_ISDIR(info.st_mode) or path.is_symlink() or path.resolve() != path:
        raise ValueError("Select an ordinary canonical private directory: " + str(path))
    if info.st_uid != os.geteuid() or info.st_mode & 0o077:
        raise ValueError("Keep this operation directory private to its native actor: " + str(path))
    return path


def exact_file(path, content, executable=False):
    path = pathlib.Path(path)
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    for parent in (path.parent, *path.parent.parents):
        if parent.is_symlink():
            raise ValueError("Do not materialize source through a symbolic directory.")
    try:
        descriptor = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0),
                             0o700 if executable else 0o600)
    except FileExistsError:
        info = path.lstat()
        if not stat.S_ISREG(info.st_mode) or info.st_size != len(content) or digest(path) != bytes_sha(content):
            raise ValueError("Retained original source differs: " + str(path))
        return
    try:
        with os.fdopen(descriptor, "wb", closefd=False) as output:
            output.write(content)
            output.flush()
            os.fsync(descriptor)
    finally:
        os.close(descriptor)
    sync_directory(path.parent)


def git(repository, arguments, env, log, data=None, optional=False):
    result = subprocess.run(["git", "--no-replace-objects", "--no-lazy-fetch", *arguments],
                            cwd=repository, env=env, input=data,
                            stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    with open(log, "ab") as output:
        os.fchmod(output.fileno(), 0o600)
        output.write(("git " + arguments[0] + " exit " + str(result.returncode) + "\n").encode())
        # A configured remote can contain credentials; keep its diagnostics private.
        output.write(result.stderr)
        output.flush()
    if result.returncode:
        if optional:
            return None
        raise RuntimeError("Original Git source operation failed (exit " + str(result.returncode) +
                           "); inspect private source-fetch.log.")
    return result.stdout


def private_git(root, intent, env):
    donor_repo = pathlib.Path(intent["repository"])
    clean = dict(env)
    for key in ("GIT_DIR", "GIT_COMMON_DIR", "GIT_OBJECT_DIRECTORY",
                "GIT_ALTERNATE_OBJECT_DIRECTORIES", "GIT_WORK_TREE"):
        clean.pop(key, None)
    log = root / "source-fetch.log"
    observed_head = git(donor_repo, ["rev-parse", "--verify", "HEAD"], clean, log, optional=True)
    original_head = observed_head.decode().strip() if observed_head else None
    object_name = git(donor_repo, ["rev-parse", "--git-path", "objects"], clean, log).decode().strip()
    objects = pathlib.Path(object_name)
    if not objects.is_absolute():
        objects = donor_repo / objects
    objects = objects.resolve(strict=True)
    directory = root / "source-git"
    if not (directory / "HEAD").exists():
        if directory.exists():
            raise ValueError("Retain and reconcile the incomplete private Git directory.")
        git(donor_repo, ["init", "--bare", "--object-format=sha1", str(directory)], clean, log)
        os.chmod(directory, 0o700)
    private_directory(directory)
    env.update({"GIT_DIR": str(directory), "GIT_COMMON_DIR": str(directory),
                "GIT_OBJECT_DIRECTORY": str(directory / "objects"),
                "GIT_ALTERNATE_OBJECT_DIRECTORIES": str(objects)})
    marker = directory / "donor-config.json"
    if not marker.exists():
        raw = git(donor_repo, ["config", "--null", "--get-regexp",
            r"^(remote\..*\.(url|fetch|promisor|partialclonefilter)|extensions\.partialclone)$"],
            clean, log, optional=True) or b""
        entries = []
        for item in raw.split(b"\0"):
            if item:
                key, value = item.split(b"\n", 1)
                entries.append((key.decode(), value.decode()))
        for key in dict.fromkeys(key for key, _ in entries):
            git(directory, ["config", "--local", "--unset-all", key], env, log, optional=True)
        for key, value in entries:
            git(directory, ["config", "--local", "--add", key, value], env, log)
        os.chmod(directory / "config", 0o600)
        # Persist the read-only alternate as well, so an independent later CLI can
        # reopen this exact private repository without inheriting our environment.
        exact_file(directory / "objects" / "info" / "alternates", (str(objects) + "\n").encode())
        save(marker, {"schema": "starforge.receiving-git-donor.v1",
                     "repository": str(donor_repo), "objects": str(objects),
                     "remoteConfigurationSha256": bytes_sha(raw)})
    observed = read(marker)
    if observed.get("repository") != str(donor_repo) or observed.get("objects") != str(objects):
        raise ValueError("The private Git source belongs to a different donor.")
    if git(directory, ["cat-file", "-e", HEAD + "^{commit}"], env, log, optional=True) is None:
        if intent["offlineSource"]:
            raise ValueError("The exact committed product is absent from the selected offline donor.")
        git(directory, ["-c", "credential.helper=", "-c", "fetch.negotiationAlgorithm=noop",
            "fetch", "--no-tags", "--no-write-fetch-head", "--no-auto-maintenance",
            "--recurse-submodules=no", "--depth=1", "--filter=blob:none", "origin", HEAD], env, log)
    actual = git(directory, ["rev-parse", "--verify", HEAD + "^{commit}"], env, log).decode().strip()
    if actual != HEAD:
        raise ValueError("The selected immutable product source differs.")
    return directory, clean, original_head

def emit(value):
    print(json.dumps(value,separators=(",",":")),flush=True)

def unpack(value):
    previous="";result={}
    for line in value.splitlines():
        left,packed=line.split("\t",1)
        prefix,suffix=left.split(":",1)
        name=previous[:int(prefix,36)]+suffix
        executable=packed.endswith("!")
        if executable: packed=packed[:-1]
        raw=base64.urlsafe_b64decode(packed+"="*((-len(packed))%4))
        if len(raw)!=20 or name in result or name.startswith("/") or "\\" in name or any(p in ("",".","..") for p in name.split("/")):
            raise ValueError("Invalid original selected source row")
        result[name]={"sha":raw.hex(),"mode":"100755" if executable else "100644"}
        previous=name
    return result

def observe_tree(repository,env,log,commit):
    observed={}
    raw=git(repository,["ls-tree","-r","-z","--full-tree",commit],env,log)
    for item in raw.split(b"\0"):
        if not item: continue
        meta,path=item.split(b"\t",1)
        mode,kind,oid=meta.decode().split(" ")
        observed[path.decode()]={"sha":oid,"mode":mode,"kind":kind}
    return observed

def verify_selection(repository,env,log,commit,rows):
    tree=observe_tree(repository,env,log,commit)
    mismatches=[p for p,r in rows.items() if tree.get(p,{}).get("sha")!=r["sha"] or tree.get(p,{}).get("mode")!=r["mode"]]
    if mismatches:
        raise ValueError("Committed source selection differs: "+json.dumps(mismatches[:12]))
    emit({"phase":"committed-source-verified","source":commit,"files":len(rows)})

def materialize(repository,env,log,rows,destination,reuse=None):
    pending={};copied=0;written=0;total=0;records=[]
    for path,row in rows.items():
        target=destination/path
        if reuse and path in reuse[1] and reuse[1][path]==row:
            source=reuse[0]/path
            raw=source.read_bytes()
            if hashlib.sha1(b"blob "+str(len(raw)).encode()+b"\0"+raw).hexdigest()!=row["sha"]:
                raise ValueError("Original materialized source changed: "+path)
            target.parent.mkdir(parents=True,exist_ok=True,mode=0o700)
            os.link(source,target)
            copied+=1;total+=len(raw)
            records.append({"path":path,"gitBlob":row["sha"],"bytes":len(raw),"sharedOriginal":True})
        else:
            pending[path]=row
    paths=list(pending)
    for start in range(0,len(paths),48):
        selected=paths[start:start+48]
        ids=list(dict.fromkeys(pending[p]["sha"] for p in selected))
        metadata=git(repository,["cat-file","--batch-check"],env,log,("\n".join(ids)+"\n").encode()).decode().splitlines()
        if len(metadata)!=len(ids): raise ValueError("Incomplete original source metadata")
        missing=[oid for oid,line in zip(ids,metadata) if line==oid+" missing"]
        if missing:
            emit({"phase":"fetching-selected-blobs","objects":len(missing),"completedFiles":copied+written})
            git(repository,["-c","credential.helper=","-c","fetch.negotiationAlgorithm=noop",
                "fetch","--no-tags","--no-write-fetch-head","--no-auto-maintenance",
                "--recurse-submodules=no","--filter=blob:none","--stdin","--","origin"],
                env,log,("\n".join(missing)+"\n").encode())
            metadata=git(repository,["cat-file","--batch-check"],env,log,("\n".join(ids)+"\n").encode()).decode().splitlines()
        sizes={}
        for oid,line in zip(ids,metadata):
            fields=line.split(" ")
            if len(fields)!=3 or fields[:2]!=[oid,"blob"]: raise ValueError("Original selected blob unavailable: "+oid)
            size=int(fields[2])
            if size<0 or size>2*1024*1024: raise ValueError("Original selected source file exceeds bound")
            sizes[oid]=size
        data=git(repository,["cat-file","--batch"],env,log,("\n".join(ids)+"\n").encode())
        blobs={};offset=0
        for oid in ids:
            end=data.index(b"\n",offset);fields=data[offset:end].decode().split(" ")
            size=sizes[oid]
            if fields!=[oid,"blob",str(size)] or data[end+size+1:end+size+2]!=b"\n":
                raise ValueError("Original selected blob framing differs")
            raw=data[end+1:end+1+size];offset=end+size+2
            if hashlib.sha1(b"blob "+str(size).encode()+b"\0"+raw).hexdigest()!=oid:
                raise ValueError("Original selected blob bytes differ")
            blobs[oid]=raw
        if offset!=len(data): raise ValueError("Unexpected original blob data")
        for path in selected:
            row=pending[path];raw=blobs[row["sha"]]
            total+=len(raw)
            if total>128*1024*1024: raise ValueError("Selected source exceeds bound")
            exact_file(destination/path,raw,row["mode"]=="100755")
            written+=1
            records.append({"path":path,"gitBlob":row["sha"],"bytes":len(raw)})
        if start%240==0:
            emit({"phase":"materializing-selected-source","directory":str(destination),"files":copied+written,"totalFiles":len(rows)})
    return {"files":len(rows),"written":written,"sharedOriginal":copied,"bytes":total,"records":records}

def safe_diagnostics(path):
    if not path.is_file(): return None
    value=path.read_text(errors="replace")[-2400:]
    value=re.sub(r"(?:https?|ssh)://[^\s]+","<configured-remote>",value)
    value=re.sub(r"(?i)(authorization|password|token)[=: ]+[^\s]+",r"\1=<redacted>",value)
    return value

